import argparse
import json
from pathlib import Path

DB = Path.home() / ".tasklite.json"


def load():
    if not DB.exists():
        return []
    return json.loads(DB.read_text())


def save(tasks):
    DB.write_text(json.dumps(tasks))


def main():
    p = argparse.ArgumentParser()
    sub = p.add_subparsers(dest="cmd")
    a = sub.add_parser("add")
    a.add_argument("text")
    sub.add_parser("list")
    d = sub.add_parser("done")
    d.add_argument("n", type=int)
    args = p.parse_args()
    tasks = load()
    if args.cmd == "add":
        tasks.append({"text": args.text, "done": False})
    elif args.cmd == "list":
        for i, t in enumerate(tasks, 1):
            print(i, "[x]" if t["done"] else "[ ]", t["text"])
    elif args.cmd == "done":
        tasks[args.n - 1]["done"] = True
    save(tasks)
